import React from 'react';
import userEvent from '@testing-library/user-event';
import { render, screen } from '@testing-library/react';
import { TextButton } from './TextButton';

describe('TextButton', () => {
  test('should render', () => {
    render(<TextButton>Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render without crashing with icon position trailing', () => {
    render(<TextButton iconPosition="trailing">Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render without crashing with icon position leading', () => {
    render(<TextButton iconPosition="leading">Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render without crashing with size small', () => {
    render(<TextButton size="small">Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render without crashing with size medium', () => {
    render(<TextButton size="medium">Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render without crashing with size large', () => {
    render(<TextButton size="large">Content</TextButton>);
    expect(screen.getByText('Content')).toBeInTheDocument();
  });

  test('should render and handle click event, calling the onClick prop callback', async () => {
    const user = userEvent.setup();
    const mockClick = jest.fn();
    render(
      <TextButton size="large" onClick={mockClick}>
        Content
      </TextButton>
    );

    await user.click(screen.getByText('Content'));

    expect(screen.getByText('Content')).toBeInTheDocument();
    expect(mockClick).toHaveBeenCalled();
  });

  test('should render and not crash handling click event, event when there is no onClick prop sent', async () => {
    const user = userEvent.setup();
    const mockClick = jest.fn();
    render(<TextButton size="large">Content</TextButton>);

    const textButton = screen.getByText('Content');

    await user.click(textButton);

    expect(textButton).toBeInTheDocument();
    expect(mockClick).not.toHaveBeenCalled();
  });
});
